import type { ComponentProps, ReactNode } from "react";
import { cn } from "./utils";

type ToolCallStatus =
    | "pending"
    | "running"
    | "succeeded"
    | "failed"
    | "awaiting-approval"
    | "denied"
    | "cancelled";

type ToolCallProps = Omit<ComponentProps<"section">, "children"> & {
    name: string;
    status: ToolCallStatus;
    input?: ReactNode;
    output?: ReactNode;
    error?: ReactNode;
    variant?: "card" | "compact";
};

const statusLabel: Record<ToolCallStatus, string> = {
    pending: "대기",
    running: "실행 중",
    succeeded: "완료",
    failed: "실패",
    "awaiting-approval": "승인 대기",
    denied: "거부됨",
    cancelled: "취소됨",
};

function hasContent(node: ReactNode) {
    return node != null && typeof node !== "boolean" &&
        !(typeof node === "string" && !node.trim());
}

function ToolCall({
    name,
    status,
    input,
    output,
    error,
    variant = "card",
    className,
    ...props
}: ToolCallProps) {
    if (typeof name !== "string" || !name.trim()) {
        throw new Error("ToolCall requires a name.");
    }
    if (!Object.hasOwn(statusLabel, status)) {
        throw new Error("ToolCall has an unsupported status.");
    }
    if (variant !== "card" && variant !== "compact") {
        throw new Error("ToolCall has an unsupported variant.");
    }
    const hasError = hasContent(error);
    if (status === "failed" && !hasError) {
        throw new Error("ToolCall failed status requires an error.");
    }
    if (hasError && status !== "failed" && status !== "denied") {
        throw new Error("ToolCall error does not match its status.");
    }
    const canShowOutput = status === "running" || status === "succeeded" ||
        status === "failed" || status === "cancelled";
    if (!canShowOutput && output != null) {
        throw new Error("ToolCall output is not available for this status.");
    }

    return (
        <section aria-label={`도구 실행: ${name}`}
            data-ui="tool-call" data-variant={variant}
            data-surface={variant === "card" ? "panel" : undefined}
            data-status={status}
            className={cn(
                "min-w-0 text-sm text-foreground",
                variant === "card"
                    ? "rounded-sm border border-border bg-surface " +
                    "p-[var(--space-3)]"
                    : "border-l-2 border-border pl-[var(--space-3)]",
                className,
            )} {...props}>
            <div data-slot={variant === "card" ? "surface-header" : undefined}
                className="flex min-w-0 items-center justify-between gap-2">
                <code data-slot="surface-title" className="min-w-0 truncate font-medium">{name}</code>
                <span role="status" className={cn(
                    "shrink-0 text-xs",
                    status === "failed" || status === "denied"
                        ? "text-danger" :
                        (status === "succeeded" || status === "running" ||
                            status === "awaiting-approval")
                            ? "text-accent" : "text-muted",
                )}>
                    {statusLabel[status]}
                </span>
            </div>
            {input != null && (
                <details className="mt-[var(--space-2)] text-muted">
                    <summary className={
                        "cursor-pointer rounded-sm text-xs " +
                        "focus-visible:outline-2 focus-visible:outline-focus"
                    }>입력 보기</summary>
                    <div className={
                        "mt-1 min-w-0 whitespace-pre-wrap break-words " +
                        "font-mono text-xs"
                    }>{input}</div>
                </details>
            )}
            {canShowOutput && output != null && (
                <div className="mt-[var(--space-2)] min-w-0">
                    <p className="m-0 text-xs font-medium text-muted">
                        {status === "succeeded" ? "결과" : "부분 결과"}
                    </p>
                    <div className="mt-1 whitespace-pre-wrap break-words">
                        {output}
                    </div>
                </div>
            )}
            {hasError && (
                <div className="mt-[var(--space-2)] min-w-0">
                    <p className="m-0 text-xs font-medium text-danger">
                        {status === "denied" ? "거부 사유" : "오류"}
                    </p>
                    <div className="mt-1 whitespace-pre-wrap break-words">
                        {error}
                    </div>
                </div>
            )}
        </section>
    );
}

export { ToolCall };
export type { ToolCallProps, ToolCallStatus };
